## Code Example
```javascript
function maxSumNonAdjacentK(a, K) {
  const n = a.length;
  const NEG = -1e15;
  // 1-based to align with recurrence
  const A = [0, ...a];
  let dpPrev = Array(K+1).fill(NEG), dpPrev2 = Array(K+1).fill(NEG), dpCur = Array(K+1).fill(NEG);
  dpPrev[0] = 0;
  if (n>=1) dpPrev2[0] = 0;
  for (let i=1;i<=n;i++){
    dpCur[0] = 0;
    for (let t=1;t<=K;t++){
      const pick = (i>=2 ? dpPrev2[t-1] : (t-1===0?0:NEG)) + A[i];
      const not = dpPrev[T];
      dpCur[t] = Math.max(not, pick);
    }
    dpPrev2 = dpPrev;
    dpPrev = dpCur;
    dpCur = Array(K+1).fill(NEG);
  }
  return dpPrev[K];
}
```

## Why This Is Asked

This question tests your understanding of counting DP, covering both memoization (top-down) and tabulation (bottom-up) approaches, along with space optimization and edge-case handling.

## Key Concepts

- Subset sum counting with each element used at most once
- Memoization (top-down) with recursive DFS and memo table
- Tabulation (bottom-up) with 1D space optimization to O(S)
- Modulo arithmetic to prevent integer overflow

## Edge Cases

- **Empty subset (N=0)**: If N=0 and S=0, return 1 (one valid subset - empty set). If S>0, return 0.
- **Target S=0**: Always return 1 (the empty subset counts as one valid subset).
- **All elements greater than S**: No valid subsets exist, return 0.

## Code Example

```javascript
function countSubsets(nums, target) {
  const mod = 1_000_000_007;
  const n = nums.length;

  // Top-down with memoization
  const memo = Array.from({ length: n + 1 }, () => Array(target + 1).fill(-1));
  function dfs(i, s) {
    if (s === 0) return 1;
    if (i === 0) return 0;
    if (memo[i][s] !== -1) return memo[i][s];
    memo[i][s] = dfs(i - 1, s) % mod;
    if (s >= nums[i - 1]) {
      memo[i][s] = (memo[i][s] + dfs(i - 1, s - nums[i - 1])) % mod;
    }
    return memo[i][s];
  }
  return dfs(n, target);
}

// Bottom-up with space optimization
function countSubsetsBU(nums, target) {
  const mod = 1_000_000_007;
  const dp = Array(target + 1).fill(0);
  dp[0] = 1;

  for (const num of nums) {
    for (let s = target; s >= num; s--) {
      dp[s] = (dp[s] + dp[s - num]) % mod;
    }
  }
  return dp[target];
}
```

Both solutions run in O(N×S) time with the bottom-up approach using O(S) space.

## Why This Is Asked
Assesses augmenting a Trie to answer prefix-based queries with dynamic weights while maintaining efficient updates. Encourages careful handling of edge cases and update semantics.

## Key Concepts
- Trie augmentation with maxSubtreeWeight; non-decreasing weight updates.
- O(len(word)) insert and O(len(s)) query.
- Edge cases: empty word input, overlapping prefixes, no matches.

## Code Example
```javascript
class Node {
  constructor() {
    this.next = new Map();
    this.wordWeight = 0;
    this.hasWord = false;
    this.maxSubtreeWeight = 0;
  }
}
class PrefixWeightTrie {
  constructor() { this.root = new Node(); }
  insert(word, weight) {
    let node = this.root;
    for (const ch of word) {
      if (!node.next.has(ch)) node.next.set(ch, new Node());
      node = node.next.get(ch);
    }
    if (!node.hasWord || weight > node.wordWeight) {
      node.hasWord = true;
      node.wordWeight = weight;
    }
    // update maxSubtreeWeight along path (omitted detailed propagation for brevity)
  }
  queryLongestPrefix(s) {
    let node = this.root;
    let bestLen = 0, bestWeight = 0;
    for (let i = 0; i < s.length; i++) {
      const c = s[i];
      if (!node.next.has(c)) break;
      node = node.next.get(c);
      if (node.maxSubtreeWeight > 0) {
        bestLen = i + 1;
        bestWeight = node.maxSubtreeWeight;
      }
    }
    return [bestLen, bestWeight];
  }
}
```

## Why This Is Asked
This question blends BFS reachability, Dijkstra shortest paths, and counting shortest paths via a DAG and topological order.

## Key Concepts
- BFS/DFS reachability
- Dijkstra's algorithm
- Shortest-path DAG
- Topological DP and modular counting

## Code Example
```javascript
function countShortestPaths(n, adj, s) {
  const dist = Array(n).fill(Infinity); dist[s] = 0;
  // priority queue based Dijkstra (pseudo-notation)
  const pq = new MinPQ((a,b)=>a[0]-b[0]);
  pq.enqueue([0,s]);
  while(!pq.isEmpty()){
    const [d,u] = pq.dequeue(); if (d!==dist[u]) continue;
    for (const {to:v, w} of adj[u]){
      if (dist[v] > d + w){ dist[v] = d + w; pq.enqueue([dist[v], v]); }
    }
  }
  const dag = Array.from({length:n}, ()=>[]);
  for (let u=0; u<n; u++) for (const {to:v, w} of adj[u]) if (dist[u] + w === dist[v]) dag[u].push(v);
  const order = Array.from({length:n}, (_,i)=>i).sort((a,b)=>dist[a]-dist[b]);
  const MOD = 1000000007; const ways = Array(n).fill(0); ways[s] = 1;
  for (const u of order) for (const v of dag[u]) ways[v] = (ways[v] + ways[u]) % MOD;
  return {dist, ways};
}
```

